// TestMigrateShadowBranch_ReconcilePath tests that when HEAD carries the
// session's LastCheckpointID as an Entire-Checkpoint trailer, the reconcile
// path fires: BaseCommit and AttributionBaseCommit both update to HEAD, and
// the old shadow branch is NOT renamed or deleted.
func TestMigrateShadowBranch_ReconcilePath(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)

	// Create commit A with checkpoint trailer
	testutil.WriteFile(t, dir, "f.txt", "v1")
	testutil.GitAdd(t, dir, "f.txt")
	testutil.GitCommit(t, dir, "checkpoint\n\nEntire-Checkpoint: abc123def456")
	commitA := testutil.GetHeadHash(t, dir)

	// Create commit B (no trailer) — simulates the "pull" that moved HEAD
	testutil.WriteFile(t, dir, "f.txt", "v2")
	testutil.GitAdd(t, dir, "f.txt")
	testutil.GitCommit(t, dir, "follow-up")
	commitB := testutil.GetHeadHash(t, dir)

	repo, err := git.PlainOpen(dir)
	if err != nil {
		t.Fatalf("PlainOpen: %v", err)
	}

	// Create a shadow branch at B to verify it is NOT renamed
	testutil.CreateBranch(t, dir, "entire/"+commitB[:7]+"-000000")

	cpID, _ := checkpointID.NewCheckpointID("abc123def456")

	state := &SessionState{
		BaseCommit:            commitB,
		AttributionBaseCommit: commitB,
		LastCheckpointID:      cpID,
		WorktreeID:            "",
	}

	// Reset HEAD back to A (simulates git reset --hard)
	testutil.GitReset(t, dir, commitA)

	s := &ManualCommitStrategy{}
	migrated, err := s.migrateShadowBranchIfNeeded(context.Background(), repo, state)
	if err != nil {
		t.Fatalf("migrateShadowBranchIfNeeded: %v", err)
	}
	if !migrated {
		t.Fatal("expected migrated=true for reconcile path")
	}
	if state.BaseCommit != commitA {
		t.Errorf("BaseCommit = %q, want %q", state.BaseCommit, commitA)
	}
	if state.AttributionBaseCommit != commitA {
		t.Errorf("AttributionBaseCommit = %q, want %q", state.AttributionBaseCommit, commitA)
	}

	// Old shadow branch at B should still exist (not renamed or deleted)
	if !testutil.BranchExists(t, dir, "entire/"+commitB[:7]+"-000000") {
		t.Error("old shadow branch was deleted or renamed, expected it to be preserved")
	}
}

