// TestShadow_ResetToKnownCheckpointReconciles tests the full reconcile flow:
// ACTIVE session condenses a checkpoint → agent-driven pull advances HEAD →
// git reset --hard back to the condensed commit → SaveStep fires →
// state reconciled, old shadow branch preserved.
func TestShadow_ResetToKnownCheckpointReconciles(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)
	defer env.Cleanup()

	// Setup: repo with initial commit
	env.InitRepo()
	env.WriteFile("README.md", "init")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.InitEntire()

	// Start session, create a checkpoint, and commit with trailer
	sess := env.NewSession()
	env.SimulateUserPromptSubmitWithPrompt(sess.ID, "Add feature")
	env.WriteFile("feature.go", "package main\nfunc Feature() {}\n")
	sess.CreateTranscript("Add feature", []FileChange{
		{Path: "feature.go", Content: "package main\nfunc Feature() {}\n"},
	})
	env.SimulateSaveStep(sess.ID, "feature.go")
	condensedCommit := env.CommitAll("Add feature") // This triggers PostCommit with trailer

	// Record state after condensation
	store, _ := session.NewStateStore(env.Ctx())
	stateAfterCondense, _ := store.Load(env.Ctx(), sess.ID)
	if stateAfterCondense.LastCheckpointID.IsEmpty() {
		t.Fatal("expected LastCheckpointID to be set after condensation")
	}
	checkpointID := stateAfterCondense.LastCheckpointID.String()

	// Simulate agent-driven pull: create a commit on top
	env.WriteFile("pulled.txt", "from remote")
	env.GitAdd("pulled.txt")
	env.GitCommit("Simulate pull")
	pulledCommit := env.GetHeadHash()

	// Fire SaveStep to trigger migration (BaseCommit should advance)
	env.SimulateSaveStep(sess.ID, "pulled.txt")
	stateAfterMigration, _ := store.Load(env.Ctx(), sess.ID)
	if stateAfterMigration.BaseCommit != pulledCommit {
		t.Fatalf("expected BaseCommit=%s after migration, got %s", pulledCommit[:7], stateAfterMigration.BaseCommit[:7])
	}

	// Reset back to the condensed commit
	cmd := exec.CommandContext(env.Ctx(), "git", "reset", "--hard", condensedCommit)
	cmd.Dir = env.Dir()
	cmd.Env = testutil.GitIsolatedEnv()
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git reset: %v\n%s", err, out)
	}

	// Fire SaveStep again — reconcile should fire
	env.SimulateSaveStep(sess.ID, "feature.go")
	stateAfterReconcile, _ := store.Load(env.Ctx(), sess.ID)

	if stateAfterReconcile.BaseCommit != condensedCommit {
		t.Errorf("BaseCommit after reconcile = %s, want %s", stateAfterReconcile.BaseCommit[:7], condensedCommit[:7])
	}
	if stateAfterReconcile.AttributionBaseCommit != condensedCommit {
		t.Errorf("AttributionBaseCommit after reconcile = %s, want %s", stateAfterReconcile.AttributionBaseCommit[:7], condensedCommit[:7])
	}

	// Verify old shadow branch at pulledCommit still exists
	if !testutil.BranchExists(t, env.Dir(), "entire/"+pulledCommit[:7]) {
		t.Error("old shadow branch was deleted, expected it to be preserved")
	}

	t.Logf("Reconcile succeeded: checkpoint %s, condensed=%s, pulled=%s", checkpointID, condensedCommit[:7], pulledCommit[:7])
}
```

