func GitReset(t *testing.T, dir string, ref string) {
	t.Helper()
	cmd := exec.Command("git", "reset", "--hard", ref)
	cmd.Dir = dir
	cmd.Env = GitIsolatedEnv()
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git reset --hard %s: %v\n%s", ref, err, out)
	}
}

// BranchExists checks whether a branch ref exists.
func BranchExists(t *testing.T, dir string, name string) bool {
	t.Helper()
	cmd := exec.Command("git", "rev-parse", "--verify", "refs/heads/"+name)
	cmd.Dir = dir
	cmd.Env = GitIsolatedEnv()
	return cmd.Run() == nil
}
